package manifest_test

import (
	"go/ast"
	goparser "go/parser"
	"go/token"
	"path/filepath"
	"slices"
	"strings"
	"testing"

	"github.com/teandresmith/sqlgen/cmd/sqlgen/config"
	"github.com/teandresmith/sqlgen/cmd/sqlgen/manifest"
	"github.com/teandresmith/sqlgen/parser"
)

// generatedSentinelsPath points at a checked-in generated package. It is
// regenerated by `make update-golden-e2e`, so a change to error.go.tmpl shows
// up here and this test catches the divergence.
const generatedSentinelsPath = "../testdata/examples/postgres/models/errors_gen.go"

// TestErrorSentinelsMatchGeneratedPackage is the drift guard for
// conventions.error_sentinels against the generated package.
//
// conventions.error_sentinels is a hardcoded list in the builder — error.go.tmpl
// is human-authored prose with per-sentinel doc comments, so there is no data
// source to derive it from. This test supplies the guarantee instead: every
// sentinel the manifest attributes to the generated package must be declared
// there, and every sentinel declared there must be advertised. The defect it
// exists to prevent shipped four names that resolve nowhere (ErrConflict,
// ErrBadReference, ErrInvalidInput, ErrForbidden — PRD §26.5.5 GraphQL codes
// PascalCased into a name column) while omitting six that do exist.
func TestErrorSentinelsMatchGeneratedPackage(t *testing.T) {
	declared := sentinelsDeclaredIn(t, generatedSentinelsPath)
	if len(declared) == 0 {
		t.Fatalf("parsed no sentinels out of %s — the fixture moved or the errors template changed shape", generatedSentinelsPath)
	}

	doc := buildFixtureManifest(t)
	var advertised []string
	for _, s := range doc.Conventions.ErrorSentinels {
		if s.Package == doc.Package {
			advertised = append(advertised, s.Name)
		}
	}
	slices.Sort(advertised)

	for _, name := range advertised {
		if !slices.Contains(declared, name) {
			t.Errorf("conventions.error_sentinels advertises %q in package %q, but %s declares no such symbol; declared = %v",
				name, doc.Package, filepath.Base(generatedSentinelsPath), declared)
		}
	}
	for _, name := range declared {
		if !slices.Contains(advertised, name) {
			t.Errorf("%s declares %q but conventions.error_sentinels omits it; advertised = %v",
				filepath.Base(generatedSentinelsPath), name, advertised)
		}
	}
}

// TestErrorSentinelsCarryQualifiedPackages pins the qualification rule across
// all three sites that name sentinels: error_sentinels[] holds bare names
// because it carries a package column, while features.tenancy.*_error and
// methods[].errors carry no package field and so qualify anything living
// outside the generated package.
func TestErrorSentinelsCarryQualifiedPackages(t *testing.T) {
	doc := buildFixtureManifest(t)
	for _, s := range doc.Conventions.ErrorSentinels {
		if strings.Contains(s.Name, ".") {
			t.Errorf("error_sentinels[%q].name is qualified; this shape carries a separate package field (%q)", s.Name, s.Package)
		}
		if s.Package == "" {
			t.Errorf("error_sentinels[%q].package is empty; the schema requires it", s.Name)
		}
	}
	for _, e := range doc.Entities {
		if e.Features.Tenancy == nil {
			continue
		}
		for field, val := range map[string]string{
			"missing_resolver_error": e.Features.Tenancy.MissingResolverError,
			"mismatch_error":         e.Features.Tenancy.MismatchError,
		} {
			if val != "" && !strings.HasPrefix(val, "tenancy.") {
				t.Errorf("entity %q features.tenancy.%s = %q, want a tenancy.-qualified sentinel", e.Name, field, val)
			}
		}
	}
}

// TestMethodErrorsNameRealSentinels is the drift guard for the most directly
// damaging site of sentinel drift: methods[].errors is what an agent reads
// to write a handler for one method, and it carried ErrConflict /
// ErrBadReference / ErrInvalidInput on every Create / Update / Upsert of every
// table. Every entry must be either a bare sentinel the generated package
// declares, or qualified by the runtime package that owns it — nothing else.
func TestMethodErrorsNameRealSentinels(t *testing.T) {
	declared := sentinelsDeclaredIn(t, generatedSentinelsPath)
	// Sentinels reachable from generated code but owned by a runtime package,
	// so they can never appear bare. Keep in sync with the templates under
	// cmd/sqlgen/gen/templates/.
	qualified := map[string]bool{
		"tenancy.ErrMissing":                  true,
		"tenancy.ErrMismatch":                 true,
		"database.ErrRefreshConcurrentlyInTx": true,
	}

	doc := buildFixtureManifest(t)
	var checked int
	for _, e := range doc.Entities {
		for _, group := range [][]manifest.Method{e.Methods.Query, e.Methods.Mutation} {
			for _, m := range group {
				for _, name := range m.Errors {
					checked++
					if qualified[name] {
						continue
					}
					if strings.Contains(name, ".") {
						t.Errorf("entity %q method %q lists %q, which is qualified by a package that owns no known sentinel", e.Name, m.Name, name)
						continue
					}
					if !slices.Contains(declared, name) {
						t.Errorf("entity %q method %q lists %q, which %s does not declare and which is not a known qualified sentinel; declared = %v",
							e.Name, m.Name, name, filepath.Base(generatedSentinelsPath), declared)
					}
				}
			}
		}
	}
	if checked == 0 {
		t.Fatal("no methods[].errors entries were checked — the fixture stopped emitting mutation methods")
	}
}

// sentinelsDeclaredIn extracts the Err* identifiers from the top-level var
// declarations of a generated errors file.
func sentinelsDeclaredIn(t *testing.T, path string) []string {
	t.Helper()
	file, err := goparser.ParseFile(token.NewFileSet(), path, nil, goparser.SkipObjectResolution)
	if err != nil {
		t.Fatalf("parse %s: %v", path, err)
	}
	var out []string
	for _, decl := range file.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.VAR {
			continue
		}
		for _, spec := range gd.Specs {
			vs, ok := spec.(*ast.ValueSpec)
			if !ok {
				continue
			}
			for _, name := range vs.Names {
				if strings.HasPrefix(name.Name, "Err") {
					out = append(out, name.Name)
				}
			}
		}
	}
	slices.Sort(out)
	return out
}

// buildFixtureManifest builds a manifest over a tenanted single-PK table, so
// both the conventions block and a populated features.tenancy are in scope.
func buildFixtureManifest(t *testing.T) *manifest.Document {
	t.Helper()
	cfg := baseConfig()
	cfg.Tenancy = &config.TenancyConfig{Enabled: true, Column: "workspace_id"}
	schema := &parser.Schema{
		Tables: []parser.Table{
			{
				Name: "documents",
				Columns: []parser.Column{
					{Name: "id", Type: "uuid", PrimaryKey: true},
					{Name: "workspace_id", Type: "uuid", Nullable: false},
					{Name: "title", Type: "text"},
				},
			},
		},
	}
	doc, err := manifest.Build(testBuildInput(t, schema, cfg))
	if err != nil {
		t.Fatalf("Build: %v", err)
	}
	return doc
}
